command:
cat <<'PERL' > /tmp/scan.pl
use strict; use warnings;
my $f=shift;
open(my $fh,'<',$f) or die $!; binmode $fh; local $/; my $d=<$fh>; close $fh;
printf "FILE %s size=%d\n",$f,length($d);
printf "SIGHEX %s\n",unpack("H*",substr($d,0,64));
my $i=0;
while((my $p=index($d,'ustar',$i))>=0){
  my $h=$p-257;
  if($h>=0){
    my $name=substr($d,$h,100); $name=~s/\0.*//s;
    my $szs=substr($d,$h+124,12); $szs=~s/[^0-7]//g; my $sz=length($szs)?oct($szs):0;
    printf "USTAR off=%d header=%d name=[%s] size=%d\n",$p,$h,$name,$sz;
    if($name=~/launchcode/){
      my $c=substr($d,$h+512,$sz);
      printf "CONTENT_HEX %s\n",unpack("H*",$c);
      my $a=$c; $a=~s/[^\x20-\x7e]/./g; printf "CONTENT_ASC %s\n",$a;
    }
  }
  $i=$p+1;
}
$i=0;
while((my $p=index($d,'PASSWORD=',$i))>=0){
  my $st=$p>16?$p-16:0; my $s=substr($d,$st,240);
  printf "PWD off=%d HEX %s\n",$p,unpack("H*",$s);
  my $a=$s; $a=~s/[^\x20-\x7e]/./g; print "PWD_ASC $a\n";
  $i=$p+9;
}
while($d=~/(8XD[A-Z0-9]{0,60})/g){ printf "8XD off=%d [%s]\n",$-[1],$1; }
while($d=~/([A-Z0-9]{0,60}W54)/g){ printf "W54 off=%d [%s]\n",$-[1],$1; }
my $n=0;
while($d=~/([A-Z0-9]{20,})/g){ printf "RUN off=%d len=%d [%s]\n",$-[1],length($1),$1; last if ++$n>=30; }
PERL
f=/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat
perl /tmp/scan.pl "$f" | head -120
echo '=== grep offsets ==='
grep -aboE 'PASSWORD=|ustar|launchcode|8XD|W54' "$f" | head -60
